12	beforeEach(function (): void {
13	    $this->tempRoot = sys_get_temp_dir().'/orbit-skill-install-test-'.bin2hex(random_bytes(4));
14	    $this->tempHome = $this->tempRoot.'/home';
15	    $this->checkoutRoot = $this->tempRoot.'/checkout';
16	    $this->sourceSkillPath = $this->checkoutRoot.'/.agents/skills/orbit';
17	
18	    File::deleteDirectory($this->tempRoot);
19	    File::ensureDirectoryExists($this->sourceSkillPath);
20	    file_put_contents(filename: $this->sourceSkillPath.'/SKILL.md', data: "# Orbit skill\n");
21	
22	    $this->previousHome = getenv('HOME');
23	    $this->previousInstallPath = getenv('ORBIT_INSTALL_PATH');
24	
25	    putenv("HOME={$this->tempHome}");
26	    putenv("ORBIT_INSTALL_PATH={$this->checkoutRoot}");
27	});
28	
29	afterEach(function (): void {
30	    $this->previousHome === false ? putenv('HOME') : putenv("HOME={$this->previousHome}");
31	    $this->previousInstallPath === false
32	        ? putenv('ORBIT_INSTALL_PATH')
33	        : putenv("ORBIT_INSTALL_PATH={$this->previousInstallPath}");
34	
35	    File::deleteDirectory($this->tempRoot);
36	});
