38	/**
39	 * @return array{int, string}
40	 */
41	function run_skill_install_command(object $test, array $params = []): array
42	{
43	    return runCommand(test: $test, command: 'skill:install', params: $params);
44	}
45	
46	function skill_install_target(string $home, string $provider): string
47	{
48	    return match ($provider) {
49	        'codex' => rtrim(string: $home, characters: '/').'/.agents/skills/orbit',
50	        'claude' => rtrim(string: $home, characters: '/').'/.claude/skills/orbit',
51	        'antigravity' => rtrim(string: $home, characters: '/').'/.gemini/config/skills/orbit',
52	        'grok' => rtrim(string: $home, characters: '/').'/.grok/skills/orbit',
53	        default => throw new InvalidArgumentException("Unknown provider {$provider}"),
54	    };
55	}
56	
57	describe('skill:install', function (): void {
58	    it('is registered with the expected signature options', function (): void {
59	        $command = app(\Illuminate\Contracts\Console\Kernel::class)->all()['skill:install'] ?? null;
60	
61	        expect($command)->not->toBeNull()->and($command->getDefinition()->getOptions())->toHaveKeys(['force', 'json']);
62	    });
63	
64	    describe('validation', function (): void {
65	        it('fails with validation_failed when no provider or path is provided', function (): void {
66	            [$exitCode, $output] = run_skill_install_command($this, ['--json' => true]);
67	
68	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
69	
70	            expect($exitCode)->toBe(1)->and($decoded['error']['code'])->toBe('validation_failed');
71	        });
72	
73	        it('fails with validation_failed when an explicit path is followed by another path', function (): void {
74	            [$exitCode, $output] = run_skill_install_command($this, [
75	                'provider' => 'unknown',
76	                'path' => '/tmp/custom-skill',
77	                '--json' => true,
78	            ]);
79	
80	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
81	
82	            expect($exitCode)
83	                ->toBe(1)
84	                ->and($decoded['error']['code'])
85	                ->toBe('validation_failed')
86	                ->and($decoded['error']['meta']['field'])
87	                ->toBe('path')
88	                ->and($decoded['error']['meta']['reason'])
89	                ->toBe('unexpected_path');
90	        });
91	
92	        it('fails with validation_failed when a provider default needs HOME and HOME is missing', function (): void {
93	            putenv('HOME');
94	
95	            [$exitCode, $output] = run_skill_install_command($this, [
96	                'provider' => 'codex',
97	                '--json' => true,
98	            ]);
99	
100	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
101	
102	            expect($exitCode)
103	                ->toBe(1)
104	                ->and($decoded['error']['code'])
105	                ->toBe('validation_failed')
106	                ->and($decoded['error']['meta']['reason'])
107	                ->toBe('missing_home');
108	        });
109	    });
110	
111	    describe('provider defaults', function (): void {
112	        it('installs to each provider default target', function (string $provider): void {
113	            $target = skill_install_target($this->tempHome, $provider);
114	
115	            [$exitCode, $output] = run_skill_install_command($this, [
116	                'provider' => $provider,
117	                '--json' => true,
118	            ]);
119	
120	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
121	
122	            expect($exitCode)
123	                ->toBe(0)
124	                ->and($decoded['success']['data']['provider'])
125	                ->toBe($provider)
126	                ->and($decoded['success']['data']['target'])
127	                ->toBe($target)
128	                ->and($decoded['success']['data']['action'])
129	                ->toBe('installed')
130	                ->and(is_file($target.'/SKILL.md'))
131	                ->toBeTrue();
132	        })->with(['codex', 'claude', 'antigravity', 'grok']);
133	    });
134	
135	    describe('explicit path', function (): void {
136	        it('treats a lone positional as an explicit target path when it is not a known provider', function (): void {
137	            $target = $this->tempRoot.'/custom/orbit-skill';
138	
139	            [$exitCode, $output] = run_skill_install_command($this, [
140	                'provider' => $target,
141	                '--json' => true,
142	            ]);
143	
144	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
145	
146	            expect($exitCode)
147	                ->toBe(0)
148	                ->and($decoded['success']['data']['provider'])
149	                ->toBeNull()
150	                ->and($decoded['success']['data']['target'])
151	                ->toBe($target)
152	                ->and(is_file($target.'/SKILL.md'))
153	                ->toBeTrue();
154	        });
155	
156	        it('installs to an explicit path when provider and path are both provided', function (): void {
157	            $target = $this->tempRoot.'/providers/codex-custom';
158	
159	            [$exitCode, $output] = run_skill_install_command($this, [
160	                'provider' => 'codex',
161	                'path' => $target,
162	                '--json' => true,
163	            ]);
164	
165	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
166	
167	            expect($exitCode)
168	                ->toBe(0)
169	                ->and($decoded['success']['data']['provider'])
170	                ->toBe('codex')
171	                ->and($decoded['success']['data']['target'])
172	                ->toBe($target)
173	                ->and(is_file($target.'/SKILL.md'))
174	                ->toBeTrue();
175	        });
176	    });
177	
178	    describe('overwrite protection', function (): void {
179	        it('fails before mutating an existing target without --force', function (): void {
180	            $target = skill_install_target(home: $this->tempHome, provider: 'codex');
181	            File::ensureDirectoryExists($target);
182	            file_put_contents(filename: $target.'/SKILL.md', data: "# stale\n");
183	
184	            [$exitCode, $output] = run_skill_install_command($this, [
185	                'provider' => 'codex',
186	                '--json' => true,
187	            ]);
188	
189	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
190	
191	            expect($exitCode)
192	                ->toBe(1)
193	                ->and($decoded['error']['code'])
194	                ->toBe('validation_failed')
195	                ->and(file_get_contents($target.'/SKILL.md'))
196	                ->toBe("# stale\n");
197	        });
198	
199	        it('overwrites an existing target when --force is provided', function (): void {
200	            $target = skill_install_target(home: $this->tempHome, provider: 'codex');
201	            File::ensureDirectoryExists($target);
202	            file_put_contents(filename: $target.'/SKILL.md', data: "# stale\n");
203	
204	            [$exitCode, $output] = run_skill_install_command($this, [
205	                'provider' => 'codex',
206	                '--force' => true,
207	                '--json' => true,
208	            ]);
209	
210	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
211	
212	            expect($exitCode)
213	                ->toBe(0)
214	                ->and($decoded['success']['data']['action'])
215	                ->toBe('installed')
216	                ->and(file_get_contents($target.'/SKILL.md'))
217	                ->toBe("# Orbit skill\n");
218	        });
219	
220	        it('overwrites an existing file target when --force is provided', function (): void {
221	            $target = $this->tempRoot.'/file-target';
222	            File::ensureDirectoryExists(dirname($target));
223	            file_put_contents(filename: $target, data: 'stale');
224	
225	            [$exitCode, $output] = run_skill_install_command($this, [
226	                'provider' => $target,
227	                '--force' => true,
228	                '--json' => true,
229	            ]);
230	
231	            $decoded = json_decode($output, associative: true, flags: JSON_THROW_ON_ERROR);
232	
233	            expect($exitCode)
234	                ->toBe(0)
235	                ->and($decoded['success']['data']['target'])
236	                ->toBe($target)
237	                ->and(is_dir($target))
238	                ->toBeTrue()
239	                ->and(file_get_contents($target.'/SKILL.md'))
240	                ->toBe("# Orbit skill\n");
241	        });
242	    });
243	
244	    describe('local-only behavior', function (): void {
245	        it('does not call the gateway', function (): void {
246	            fakeGateway(fakeSuccessEnvelope(['nodes' => []]));
247	
248	            [$exitCode] = run_skill_install_command($this, [
249	                'provider' => 'codex',
250	                '--json' => true,
251	            ]);
252	
253	            expect($exitCode)->toBe(0);
254	            Http::assertNothingSent();
255	        });
256	    });
257	
258	    describe('human output', function (): void {
259	        it('renders key value lines on success', function (): void {
260	            [$exitCode, $output] = run_skill_install_command($this, ['provider' => 'codex']);
261	
262	            expect($exitCode)
263	                ->toBe(0)
264	                ->and($output)
265	                ->toContain('action: installed')
266	                ->and($output)
267	                ->toContain('provider: codex');
268	        });
269	
270	        it('renders code:message on validation failure', function (): void {
271	            [$exitCode, $output] = run_skill_install_command($this);
272	
273	            expect($exitCode)->toBe(1)->and($output)->toStartWith('validation_failed:');
274	        });
275	    });
276	});
